@Composable
fun ResourceTag(icon: ImageVector, value: String) {
    Surface(
        shape = RoundedCornerShape(16.dp),
        color = Color(0xFFF1F5F9),
        modifier = Modifier.height(32.dp)
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Icon(imageVector = icon, contentDescription = null, modifier = Modifier.size(18.dp), tint = Color(0xFFFFA000))
            Spacer(modifier = Modifier.width(4.dp))
            Text(text = value, fontWeight = FontWeight.Bold, fontSize = 13.sp)
            Icon(imageVector = Icons.Default.Add, contentDescription = null, modifier = Modifier.size(14.dp), tint = Color.Gray)
        }
    }
}
@Composable
fun QuizTreeBanner(screenWidth: Dp) {
    var startAnim by remember { mutableStateOf(false) }
    LaunchedEffect(Unit) {
        startAnim = true
    }

    // Ekranın en sağından soluna doğru ilerlesin
    val animatedOffset by animateDpAsState(
        targetValue = if (startAnim) 0.dp else screenWidth,
        animationSpec = tween(durationMillis = 1500, easing = FastOutSlowInEasing),
        label = "cat_slide"
    )

    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(16.dp)
            .height(160.dp),
        shape = RoundedCornerShape(24.dp),
        elevation = CardDefaults.cardElevation(4.dp)
    ) {
        Box(modifier = Modifier.fillMaxSize().background(
            Brush.horizontalGradient(listOf(Color(0xFFE0EAFC), Color(0xFFCFDEF3)))
        )) {
            // 🐱 Profesör Kedi (Sağdan Sola Hareketi, Sığdırma ve Sona Doğru Solma)
            Image(
                painter = painterResource(id = R.drawable.professor_cat),
                contentDescription = null,
                contentScale = ContentScale.Crop, // Resmi kutucuğa dikeyde tam sığdır (boşluk kalmasın)
                modifier = Modifier
                    .align(Alignment.CenterEnd)
                    .fillMaxHeight()
                    .fillMaxWidth(0.70f) // Ekranın %70'inde dursun
                    .offset(x = animatedOffset)
                    .graphicsLayer(alpha = 0.99f) // DstIn blend mode offscreen buffer için gerekli
                    .drawWithContent {
                        val colors = listOf(Color.Black, Color.Transparent)
                        drawContent()
                        drawRect(
                            brush = Brush.horizontalGradient(
                                colors = colors,
                                startX = size.width * 0.55f, // Sağ tarafta daha uzun süre net kalsın (solma geç başlasın)
                                endX = 0f // Sol sınırda tamamen bitsin
                            ),
                            blendMode = BlendMode.DstIn
                        )
                    }
            )

            // ✍️ Metin Alanı (%45 Genişlik ve Kelime Bölmeme)
            Column(
                modifier = Modifier
                    .fillMaxHeight()
                    .fillMaxWidth(0.45f) // En fazla %45
                    .padding(20.dp),
                verticalArrangement = Arrangement.Center
            ) {
                Text(
                    text = "Quiz Zamanı!",
                    style = TextStyle(fontSize = 20.sp, fontWeight = FontWeight.Black, color = Color(0xFF1A2B5E)),
                    softWrap = true // Kelime bölünmez
                )
                Spacer(modifier = Modifier.height(6.dp))
                Text(
                    text = "Hemen quizleri çöz, kelimeleri pekiştirerek İngilizce ağacını büyüt!",
                    style = TextStyle(fontSize = 12.sp, color = Color(0xFF4466AA), fontWeight = FontWeight.Medium),
                    softWrap = true // Kelime bütünlüğü korunur
                )
            }
        }
    }
}
@Composable
fun FloatingBalloonButton(
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    val infiniteTransition = rememberInfiniteTransition(label = "balloon")
    val floatAnim by infiniteTransition.animateFloat(
        initialValue = -6f,
        targetValue = 6f,
        animationSpec = infiniteRepeatable(
            animation = tween(2000, easing = FastOutSlowInEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "balloon_float"
    )

    Box(
        modifier = modifier
            .offset(y = floatAnim.dp)
            .size(56.dp)
            .shadow(elevation = 6.dp, shape = CircleShape)
            .background(Color.White, CircleShape)
            .clickable { onClick() }
            .padding(8.dp),
        contentAlignment = Alignment.Center
    ) {
        Canvas(modifier = Modifier.fillMaxSize()) {
            val w = size.width
            val h = size.height
            val balloonRadius = w * 0.35f
            val balloonCenterX = w / 2f
            val balloonCenterY = h / 2f - 4f

            // String (İp)
            val path = Path().apply {
                moveTo(balloonCenterX, balloonCenterY + balloonRadius)
                quadraticTo(
                    balloonCenterX - 4f, balloonCenterY + balloonRadius + w * 0.2f,
                    balloonCenterX + 2f, balloonCenterY + balloonRadius + w * 0.4f
                )
            }
            drawPath(
                path = path,
                color = Color.LightGray,
                style = androidx.compose.ui.graphics.drawscope.Stroke(width = 2f, cap = StrokeCap.Round)
            )

            // Tie (Düğüm)
            val tiePath = Path().apply {
                moveTo(balloonCenterX, balloonCenterY + balloonRadius)
                lineTo(balloonCenterX - 4f, balloonCenterY + balloonRadius + 4f)
                lineTo(balloonCenterX + 4f, balloonCenterY + balloonRadius + 4f)
                close()
            }
            drawPath(tiePath, color = Color(0xFFF1F5F9))

            // Balloon Body (Beyaz 3D Görünüm)
            drawCircle(
                brush = Brush.radialGradient(
                    colors = listOf(Color.White, Color(0xFFE2E8F0)),
                    center = Offset(balloonCenterX - 3f, balloonCenterY - 3f),
                    radius = balloonRadius
                ),
                radius = balloonRadius,
                center = Offset(balloonCenterX, balloonCenterY)
            )

            // Shine (Parlama)
            drawCircle(
                color = Color.White.copy(alpha = 0.8f),
                radius = balloonRadius * 0.25f,
                center = Offset(balloonCenterX - balloonRadius * 0.3f, balloonCenterY - balloonRadius * 0.3f)
            )
        }
    }
}
@Composable
fun PipeConnection(width: Dp, height: Dp, pawCount: Int, isSolved: Boolean, isHorizontal: Boolean = false) {
    val color = if (isSolved) Color(0xFFD7F0D8) else Color(0xFFF2F2F2)
    val pawRes = if (isSolved) R.drawable.green_paw else R.drawable.black_paw

    Box(
        modifier = Modifier
            .size(width, height)
            .background(color), // Köşe yumuşatmayı kaldırdık ki kutulara tam otursun
        contentAlignment = Alignment.Center
    ) {
        if (isHorizontal) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                repeat(pawCount) { idx ->
                    Image(painter = painterResource(id = pawRes), contentDescription = null, modifier = Modifier.size(14.dp).padding(horizontal = 2.dp))
                }
            }
        } else {
            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                repeat(pawCount) { idx ->
                    Image(painter = painterResource(id = pawRes), contentDescription = null, modifier = Modifier.size(14.dp).padding(vertical = 2.dp))
                }
            }
        }
    }
}

@Composable
fun QuizNodeWrapper(
    step: QuizStep,
    index: Int,
    sectionIndex: Int, // Bu parametreyi eklemelisin
    lastSolvedIndex: Int,
    navController: NavController,
    unitColors: List<Color>, // Renk listesini dışarıdan almalı
    modifier: Modifier = Modifier
) {
    // 1. Soru çözüldü mü?
    val isSolved = index <= lastSolvedIndex

    // 2. Soru kilitli mi?
    val isLocked = if (index == 0) false else index > lastSolvedIndex + 1

    // 🎨 Renk ve Hizalama Hesabı (15'li döngüye göre)
    val colorIdx = (index / 15) % unitColors.size
    val currentColor = unitColors[colorIdx]

    // Yılanlama hizalaması (Sinüs)
    val posInCycle = index % 15
    val angle = (posInCycle.toFloat() / 15f) * 2f * Math.PI.toFloat()
    val horizontalBias = kotlin.math.sin(angle).toFloat() * 0.75f
    val alignment = BiasAlignment(horizontalBias, 0f)

    Box(
        modifier = modifier.fillMaxWidth(),
        contentAlignment = alignment
    ) {
        DuoQuizNode(
            step = step, // 'item.step' yerine sadece 'step'
            isSolved = isSolved,
            isLocked = isLocked,
            starCount = 0,
            sectionIndex = sectionIndex,
            nodeColor = currentColor,
            totalQuestions = 10,
            currentIndex = index,
            onClick = {
                if (!isLocked) {
                    val routeNumber = index + 1 // 'item.quizIndex' yerine 'index'
                    navController.navigate("test_$routeNumber")
                }
            }
        )
    }
}

// --- 💡 YARDIMCI COMPOSABLE: DuoQuizNode (Senin PNG'lerini çeken versiyon) ---
@Composable
fun DuoQuizNode(
    step: QuizStep,
    modifier: Modifier = Modifier,
    isSolved: Boolean,
    isLocked: Boolean,
    starCount: Int,
    blueStarCount: Int = 0,
    sectionIndex: Int,
    nodeColor: Color,
    currentIndex: Int,
    totalQuestions: Int,
    onClick: () -> Unit
) {
    val actionBlue = Color(0xFF42A5F5)
    val lockedBackground = Color(0xFFF1F5F9)

    // Yamalanan: İlk adım her zaman açık olsun mantığı
    val finalLockedState = remember(step.id, isLocked) {
        if (step.id == 1) false else isLocked
    }

    // Yamalanan: Görseldeki gibi zigzag akışı için dinamik genişlik
    val dynamicWidth = when {
        currentIndex == 0 -> 280.dp // İlk ünite geniş başlasın
        else -> 180.dp              // Diğerleri ikili sıra için dar olsun
    }

    Card(
        modifier = modifier
            .padding(vertical = 10.dp, horizontal = 12.dp)
            .width(dynamicWidth)
            .height(72.dp)
            .clickable { onClick() },
        shape = RoundedCornerShape(24.dp),
        colors = CardDefaults.cardColors(
            containerColor = if (finalLockedState) lockedBackground else Color.White
        ),
        elevation = CardDefaults.cardElevation(defaultElevation = 3.dp)
    ) {
        Row(
            modifier = Modifier.fillMaxSize().padding(horizontal = 16.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            // İkon Bölümü (Tik/Kilit)
            Box(
                modifier = Modifier
                    .size(36.dp)
                    .clip(CircleShape)
                    .background(if (isSolved) actionBlue.copy(alpha = 0.1f) else Color.Transparent)
                    .border(1.5.dp, if (finalLockedState) Color(0xFFCBD5E1) else actionBlue, CircleShape),
                contentAlignment = Alignment.Center
            ) {
                if (finalLockedState) {
                    Image(
                        painter = painterResource(id = R.drawable.padlock),
                        contentDescription = "Locked",
                        modifier = Modifier.size(24.dp)
                    )
                } else {
                    Icon(imageVector = Icons.Default.Check, contentDescription = null, tint = actionBlue, modifier = Modifier.size(20.dp))
                }
            }

            Spacer(modifier = Modifier.width(12.dp))

            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = "${step.id}. ${step.title}",
                    style = TextStyle(fontSize = 14.sp, fontWeight = FontWeight.Bold, color = if (finalLockedState) Color(0xFF94A3B8) else Color(0xFF1E293B)),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )

                if (!finalLockedState) {
                    Row(modifier = Modifier.padding(top = 2.dp)) {
                        repeat(3) { index ->
                            val starColor = when {
                                index < blueStarCount -> Color(0xFF42A5F5) // Blue Star
                                index < starCount -> Color(0xFFFFB300) // Yellow Star
                                else -> Color(0xFFE2E8F0) // Gray Star
                            }
                            Icon(
                                imageVector = Icons.Default.Star,
                                contentDescription = null,
                                modifier = Modifier.size(14.dp),
                                tint = starColor
                            )
                        }
                    }
                }
            }
        }
    }
}
